import sys

data = sys.stdin.read().split()
n = int(data[0])
t = [int(x) for x in data[1:1 + n]]
ans = 0
for i in range(n):
    for j in range(i + 1, n):
        if (t[i] + t[j]) % 60 == 0:
            ans += 1
print(ans)

